import pathlib,socket,selectors,tempfile,os,time,math
def execute(sock,source,output,timeout=3.0):
    if isinstance(timeout,bool) or not isinstance(timeout,(int,float)) or not math.isfinite(timeout) or not 0<timeout<=10:raise ValueError('timeout must be in (0,10]')
    source=pathlib.Path(source);output=pathlib.Path(output)
    if source.resolve()==output.resolve():raise ValueError('input/output must differ')
    if sock.getsockopt(socket.SOL_SOCKET,socket.SO_TYPE)!=socket.SOCK_STREAM:raise ValueError('connected stream socket required')
    sock.getpeername()
    previous=sock.gettimeout();temp=None;sent=received=0;deadline=time.monotonic()+timeout
    try:
        with source.open('rb') as incoming,selectors.DefaultSelector() as selector:
            fd,temp=tempfile.mkstemp(prefix='.duplex-',dir=output.parent)
            with os.fdopen(fd,'wb') as target:
                sock.setblocking(False);pending=b'';source_eof=False;remote_eof=False;write_closed=False
                while not (remote_eof and write_closed):
                    if not pending and not source_eof:
                        pending=incoming.read(65536)
                        if not pending:source_eof=True
                    if source_eof and not pending and not write_closed:
                        sock.shutdown(socket.SHUT_WR);write_closed=True
                    if remote_eof and write_closed:break
                    remaining=deadline-time.monotonic()
                    if remaining<=0:raise TimeoutError('total transfer deadline exceeded')
                    mask=(0 if remote_eof else selectors.EVENT_READ)|(selectors.EVENT_WRITE if pending else 0)
                    try:selector.modify(sock,mask)
                    except KeyError:selector.register(sock,mask)
                    events=selector.select(remaining)
                    if not events:raise TimeoutError('total transfer deadline exceeded')
                    for _,event in events:
                        if event & selectors.EVENT_READ:
                            try:data=sock.recv(65536)
                            except BlockingIOError:data=None
                            if data is not None:
                                if data:target.write(data);received+=len(data)
                                else:remote_eof=True
                        if event & selectors.EVENT_WRITE and pending:
                            try:count=sock.send(pending)
                            except BlockingIOError:count=None
                            if count==0:raise ConnectionError('send made no progress')
                            if count:sent+=count;pending=pending[count:]
                target.flush();os.fsync(target.fileno())
            os.replace(temp,output);temp=None
        return {'sent':sent,'received':received}
    finally:
        sock.settimeout(previous)
        if temp is not None and os.path.exists(temp):os.unlink(temp)
```

接收端不读取时，增大拥塞窗口不能替应用消费数据。用同一事件循环推进读写，及时释放接收缓冲，并按总截止时间中止；成功计数不是跨断线续传确认。

原理补充：
Zero Window说明接收端当前通告没有可接收空间，常与应用未及时读取、接收缓冲压力或处理阻塞有关，不是发送端拥塞窗口不足。沿接收进程读行为、缓冲占用及下游等待寻找原因，核对窗口探测是否能观察到重新开放。增大发送窗口可能无效并增加资源占用。验收接收应用恢复读取后窗口和吞吐回升，同时控制数据积压。扩大接收缓冲只能吸收有限突发，若处理速率长期不足仍会耗尽；不要把持续窗口关闭归为网络丢包并反复重建连接。

